<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movie Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>:root{--dark:#222;--dark2:#333;--gold:#DB9603;--gold2:#FCAC03}body{background:#f5f5f5}.sidebar{width:230px;background:var(--dark);min-height:100vh}.logo{color:#fff}.logo span{color:var(--gold2);font-size:12px}.sidebar a{display:block;color:#ccc;text-decoration:none;padding:12px;border-radius:5px;margin-bottom:5px}.sidebar a:hover,.sidebar a.active{background:var(--gold);color:#fff}.header{height:65px;background:var(--dark2)}.card-box{background:#fff;border-top:3px solid var(--gold);padding:20px;border-radius:5px;box-shadow:0 2px 8px #ddd}</style></head><body><div class="d-flex min-vh-100"><aside class="sidebar p-3"><h4 class="logo mb-4">MOVIE<span> ADMIN</span></h4><a class="active" href="index.html">Dashboard</a><a href="#">Movies</a><a href="#">Shows</a><a href="#">Bookings</a></aside><div class="flex-grow-1"><header class="header px-4 d-flex align-items-center"><h5 class="mb-0 text-white">Dashboard</h5><div class="ms-auto text-white">Admin</div></header><main class="p-4"><h2>Dashboard</h2><p class="text-muted">Movie website overview</p><div class="row g-3 my-3"><div class="col-md-3"><div class="card-box"><small>Total Movies</small><h3>25</h3></div></div><div class="col-md-3"><div class="card-box"><small>Shows</small><h3>12</h3></div></div><div class="col-md-3"><div class="card-box"><small>Bookings</small><h3>348</h3></div></div><div class="col-md-3"><div class="card-box"><small>Users</small><h3>120</h3></div></div></div><div class="card shadow-sm border-0"><div class="card-header bg-white"><b>Recent Movies</b></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Movie</th><th>Genre</th><th>Release Date</th><th>Status</th></tr></thead><tbody><tr><td>Movie Name 1</td><td>Action</td><td>20 Aug 2026</td><td><span class="badge bg-success">Active</span></td></tr><tr><td>Movie Name 2</td><td>Drama</td><td>18 Aug 2026</td><td><span class="badge bg-success">Active</span></td></tr></tbody></table></div></div></main></div></div></body></html>